parameters.jsCode:
// Normalize intent spike payloads from three possible sources:
// 1. Common Room outgoing webhook (organization payload, v1)
// 2. 6sense CRM-sync data forwarded by the Polling Cron (custom shape)
// 3. Bombora CRM-sync data forwarded by the Polling Cron (custom shape)
//
// Output: a single normalized intent record regardless of source.

const raw = $json.body || $json;

// Detect source by payload shape
let source = 'unknown';
let domain = '';
let accountName = '';
let employeeCount = null;
let industry = '';
let country = '';
let intentScore = null;
let buyingStage = '';
let topTopics = [];
let technologies = [];
let sfdcAccountId = '';
let crAccountId = '';
let spikeSeverity = 'medium'; // low | medium | high

if (raw.type === 'organization' || raw.version) {
  // Common Room organization webhook
  source = 'common-room';
  domain = raw.domain || '';
  accountName = raw.name || '';
  employeeCount = raw.employeeCount || null;
  industry = raw.industry || '';
  country = raw.location?.country || '';
  technologies = Array.isArray(raw.technologies) ? raw.technologies.slice(0, 10) : [];
  // Common Room passes custom fields for intent score if 6sense is connected via Salesforce
  intentScore = raw.customFields?.sixsense_intent_score || raw.intentScore || null;
  buyingStage = raw.customFields?.sixsense_buying_stage || raw.buyingStage || '';
  topTopics = raw.customFields?.bombora_top_topics?.split(',').map(t => t.trim()) || [];
  crAccountId = raw.commonRoomOrgLink || '';
  sfdcAccountId = raw.customFields?.sfdc_account_id || '';

} else if (raw._source === '6sense') {
  // 6sense CRM-sync data forwarded by Polling Cron
  source = '6sense';
  domain = raw.domain || '';
  accountName = raw.account_name || '';
  employeeCount = raw.employee_count || null;
  industry = raw.industry || '';
  country = raw.country || '';
  intentScore = raw.intent_score || null;
  buyingStage = raw.buying_stage || '';
  topTopics = Array.isArray(raw.top_topics) ? raw.top_topics.slice(0, 8) : [];
  sfdcAccountId = raw.sfdc_account_id || '';
  technologies = Array.isArray(raw.technologies) ? raw.technologies.slice(0, 10) : [];

} else if (raw._source === 'bombora') {
  // Bombora CRM-sync data forwarded by Polling Cron
  source = 'bombora';
  domain = raw.domain || '';
  accountName = raw.company_name || '';
  employeeCount = raw.company_size || null;
  industry = raw.industry || '';
  country = raw.country || '';
  intentScore = raw.composite_score || null;
  buyingStage = raw.surge_level || ''; // low / medium / high
  topTopics = Array.isArray(raw.topics) ? raw.topics.map(t => t.topic || t).slice(0, 8) : [];
  sfdcAccountId = raw.sfdc_account_id || '';
  technologies = [];

} else {
  // Fallback: try to pull common fields from whatever shape was sent
  source = 'generic';
  domain = raw.domain || raw.website || '';
  accountName = raw.name || raw.account_name || raw.company_name || '';
  employeeCount = raw.employeeCount || raw.employee_count || null;
  industry = raw.industry || '';
  country = raw.country || '';
  intentScore = raw.intentScore || raw.intent_score || null;
  buyingStage = raw.buyingStage || raw.buying_stage || '';
  topTopics = Array.isArray(raw.topTopics || raw.topics) ? (raw.topTopics || raw.topics).slice(0, 8) : [];
  sfdcAccountId = raw.sfdcAccountId || raw.sfdc_account_id || '';
}

// Map buying stage / score to spike severity
// 6sense stages: Target, Awareness, Consideration, Decision, Purchase
// Bombora surge levels: low, medium, high
// Numeric scores: 0-100
const stageMap = {
  'purchase': 'high', 'decision': 'high',
  'consideration': 'medium',
  'awareness': 'low', 'target': 'low',
  'high': 'high', 'medium': 'medium', 'low': 'low'
};
if (buyingStage) {
  spikeSeverity = stageMap[buyingStage.toLowerCase()] || 'medium';
} else if (intentScore !== null) {
  if (intentScore >= 70) spikeSeverity = 'high';
  else if (intentScore >= 40) spikeSeverity = 'medium';
  else spikeSeverity = 'low';
}

// Derive a dedup key: domain + date (day-level window prevents re-firing for same account same day)
const today = new Date().toISOString().split('T')[0];
const dedupKey = `${domain}::${today}`;

if (!domain) {
  throw new Error('Normalized payload has no domain — cannot process spike without account identifier.');
}

return [{
  json: {
    source,
    domain,
    accountName,
    employeeCount,
    industry,
    country,
    intentScore,
    buyingStage,
    topTopics,
    technologies,
    sfdcAccountId,
    crAccountId,
    spikeSeverity,
    dedupKey,
    receivedAt: new Date().toISOString(),
  }
}];

// Day-level dedup using n8n workflow static data (the only correct way to persist
// cross-execution state from a Code node — there is NO public REST API for static data).
//
// $getWorkflowStaticData('global') returns a plain object that n8n persists in its DB
// after the execution finishes. NOTE: static data only persists for PRODUCTION executions
// (webhook / schedule trigger), not manual test runs.
//
// Logic:
//   1. Read the global static-data object.
//   2. Prune keys whose date is older than today (keeps the store small — addresses the
//      "static data accumulates indefinitely" failure mode without a separate cron).
//   3. If this domain+date key already exists, this is a duplicate spike today — return []
//      so no downstream node fires.
//   4. Otherwise stamp the key (mark BEFORE any external call so two concurrent spikes for
//      the same domain can't both pass) and pass the normalized payload through.

const staticData = $getWorkflowStaticData('global');

const normalized = $json;
const domain = normalized.domain;
const today = new Date().toISOString().split('T')[0]; // YYYY-MM-DD
const key = `dedup_${domain}_${today}`;

// 2. Prune stale keys (any dedup_* key not suffixed with today's date).
for (const k of Object.keys(staticData)) {
  if (k.startsWith('dedup_') && !k.endsWith(`_${today}`)) {
    delete staticData[k];
  }
}

// 3. Duplicate check.
if (staticData[key]) {
  // Already actioned this domain today — drop silently.
  return [];
}

// 4. Mark and pass through.
staticData[key] = normalized.receivedAt || new Date().toISOString();

return [{ json: { ...normalized, dedupPassed: true } }];

// Assignment logic: determine which rep owns this spike and at what urgency.
//
// Rules (in priority order):
// 1. If a Salesforce Account exists and has an Owner, that owner gets the spike — they own the account.
// 2. If no SFDC Account found, route to the SDR assignment pool based on territory:
//    - US/CA/AU/NZ → SDR_POOL_AMER (env var: SDR_POOL_AMER_EMAIL, SDR_POOL_AMER_SLACK)
//    - DE/AT/CH/FR/NL/SE/DK/NO/FI/BE → SDR_POOL_EMEA (env var: SDR_POOL_EMEA_EMAIL, SDR_POOL_EMEA_SLACK)
//    - All others → SDR_POOL_ROW (env var: SDR_POOL_ROW_EMAIL, SDR_POOL_ROW_SLACK)
// 3. Urgency: high-severity spikes get flagged urgent; mid/low get standard.

const spikeData = $('Dedup Gate (Static Data)').item.json;
const sfRecord = $json?.records?.[0] || null;

let assigneeEmail = '';
let assigneeName = '';
let assigneeSlack = '';
let sfdcAccountId = spikeData.sfdcAccountId || '';
let sfdcOwnerId = ''; // Salesforce User Id (15/18-char, starts with 005) — used as Task OwnerId
let assignmentSource = '';

if (sfRecord) {
  // Account exists in Salesforce — keep existing owner
  assigneeEmail = sfRecord.Owner?.Email || $env.SDR_POOL_AMER_EMAIL;
  assigneeName = sfRecord.Owner?.Name || 'Account Owner';
  assigneeSlack = sfRecord.Owner?.Slack_Handle__c || '';
  sfdcAccountId = sfRecord.Id || sfdcAccountId;
  sfdcOwnerId = sfRecord.OwnerId || ''; // a real User Id we can assign the Task to
  assignmentSource = 'sfdc-existing-owner';
} else {
  // No SFDC Account — territory-based pool assignment
  const country = (spikeData.country || '').toUpperCase();
  const amer = new Set(['US', 'CA', 'AU', 'NZ', 'MX', 'BR', 'AR', 'CL', 'CO']);
  const emea = new Set(['DE', 'AT', 'CH', 'FR', 'NL', 'SE', 'DK', 'NO', 'FI', 'BE', 'GB', 'IE', 'ES', 'PT', 'IT']);

  if (amer.has(country) || country === '') {
    assigneeEmail = $env.SDR_POOL_AMER_EMAIL || 'sdr-amer@example.com';
    assigneeName = 'SDR Pool — AMER';
    assigneeSlack = $env.SDR_POOL_AMER_SLACK || '';
    assignmentSource = 'pool-amer';
  } else if (emea.has(country)) {
    assigneeEmail = $env.SDR_POOL_EMEA_EMAIL || 'sdr-emea@example.com';
    assigneeName = 'SDR Pool — EMEA';
    assigneeSlack = $env.SDR_POOL_EMEA_SLACK || '';
    assignmentSource = 'pool-emea';
  } else {
    assigneeEmail = $env.SDR_POOL_ROW_EMAIL || 'sdr-row@example.com';
    assigneeName = 'SDR Pool — ROW';
    assigneeSlack = $env.SDR_POOL_ROW_SLACK || '';
    assignmentSource = 'pool-row';
  }
}

const isUrgent = spikeData.spikeSeverity === 'high';

return [{
  json: {
    ...spikeData,
    sfdcAccountId,
    sfdcOwnerId,
    assigneeEmail,
    assigneeName,
    assigneeSlack,
    assignmentSource,
    isUrgent,
    sfdcAccountFound: !!sfRecord,
    sfdcAccountName: sfRecord?.Name || spikeData.accountName,
  }
}];

