// Parse Claude's draft. Fall back to a templated placeholder if parsing fails.
const assignmentData = $('Assignment Logic').item.json;
const raw = $json?.content?.[0]?.text || '';

let draft = null;
try {
  draft = JSON.parse(raw);
} catch (e) {
  draft = null;
}

const usedFallback = !draft || !draft.subject;
const subject = draft?.subject || `[Intent spike] ${assignmentData.sfdcAccountName} is researching — follow up`;
const body = draft?.body || `Hi [Name], saw ${assignmentData.sfdcAccountName} is actively researching ${assignmentData.topTopics.slice(0, 2).join(' and ')} — thought it was worth a quick note to see if there's a fit. Happy to share what we've seen work for similar teams.`;
const talkingPoint = draft?.talking_point || `${assignmentData.sfdcAccountName} hit ${assignmentData.spikeSeverity} intent on: ${assignmentData.topTopics.slice(0, 3).join(', ')}.`;

return [{
  json: {
    ...assignmentData,
    draftSubject: subject,
    draftBody: body,
    draftTalkingPoint: talkingPoint,
    draftSource: usedFallback ? 'template-fallback' : 'claude',
  }
}];

