    Type: 'Call',
    Intent_Spike_Source__c: j.source,
    Intent_Score__c: j.intentScore != null ? j.intentScore : null,
    Intent_Buying_Stage__c: j.buyingStage || ''
  };
  // OwnerId must be a Salesforce User Id (15/18-char, starts with 005) — never an email.
  // Only set it when we resolved the account owner's User Id; otherwise omit so the Task
  // defaults to the integration (running) user. Omitting (not '') avoids MALFORMED_ID.
  if (j.sfdcOwnerId) task.OwnerId = j.sfdcOwnerId;
  // WhatId links the Task to the Account; omit when there is no Account (avoids MALFORMED_ID).
  if (j.sfdcAccountId) task.WhatId = j.sfdcAccountId;
  return JSON.stringify(task);
})() }}

