// Fan out Salesforce Account records as individual webhook POSTs to the main ingest endpoint.
// Each record is forwarded as a Bombora or 6sense CRM-sync shaped payload so
// Normalize Intent Payload can handle it.

const records = $json?.records || [];
if (!records.length) return [];

return records.map(r => ({
  json: {
    _forwardTo: `${$env.N8N_SELF_URL_HOST}/webhook/intent-spike-handler`,
    payload: {
      // Use 6sense fields if populated, else fall back to Bombora fields
      _source: r.sixsense_Intent_Score__c ? '6sense' : 'bombora',
      domain: (r.Website || '').replace(/^https?:\/\/(www\.)?/, '').split('/')[0],
      account_name: r.Name,
      company_name: r.Name,
      employee_count: r.NumberOfEmployees,
      industry: r.Industry,
      country: r.BillingCountry,
      intent_score: r.sixsense_Intent_Score__c || null,
      buying_stage: r.sixsense_Buying_Stage__c || null,
      composite_score: r.Bombora_Composite_Score__c || null,
      surge_level: r.Bombora_Surge_Level__c || null,
      top_topics: r.sixsense_Top_Topics__c
        ? r.sixsense_Top_Topics__c.split(';').map(t => t.trim())
        : (r.Bombora_Top_Topics__c ? r.Bombora_Top_Topics__c.split(';').map(t => t.trim()) : []),
      sfdc_account_id: r.Id,
    }
  }
}));
